{
  "verdict": "correction_required",
  "humanApproval": false,
  "findings": [
    {
      "severity": "high",
      "file": "packages/workflow-control/src/deliveryBrokers.ts",
      "location": "DurableDeliveryBroker.execute, #replayMutation; gitDeliveryPort.ts: LocalGitDeliveryPort.mutate",
      "reason": "Ordinary delivery mutations remain outside a guarded dispatch transaction. #assertReady finishes its verification and transaction before calling port.mutate. Another process can invalidate approval or take over the lease before the actual Git write. The supplied before_mutation fault hook also exposes this gap deterministically. Non-bootstrap LocalGitDeliveryPort performs no document or lease check at update-ref; its commit path additionally performs multiple blocking Git commands before writing. A subsequent commitDeliveryOperation rejection cannot undo an unauthorized effect already performed.",
      "proposedFix": "Guard each actual delivery effect with fresh document verification and approval/cancellation/lease checks under the writer reservation that initiates it. Carry this guard through production adapters to the actual write, including writes following observations. Add real Git regressions that invalidate approval, change documents or replace leases after readiness checks and assert zero subsequent writes."
    },
    {
      "severity": "high",
      "file": "packages/workflow-control/src/gitDeliveryPort.ts",
      "location": "LocalGitDeliveryPort constructor and #createExactCommitLocked; documentApproval.ts: verifyCurrentSources",
      "reason": "The document verifier and ordinary Git commit adapter can use different workspaces. Verification resolves the registered worktree for the accepted task ref, while the non-bootstrap Git adapter fixes #sourceRoot to the canonical workspace and runs git add there. With unchanged approved documents in the task worktree but changed documents in the canonical workspace, verification passes while an otherwise permitted exact-tree commit can import the changed normative bytes from the canonical workspace. The commit settlement check again reads the task worktree, so it does not establish that the committed tree contains approved document bytes.",
      "proposedFix": "Bind the delivery adapter's actual source to the trusted accepted task workspace and verify that exact source. Before committing or adopting a tree, verify its normative document blobs against the manifest. Add a two-worktree regression with clean task documents and changed canonical-workspace documents, using the real Git adapter."
    },
    {
      "severity": "high",
      "file": "packages/workflow-control/src/storage.ts",
      "location": "dispatchSchedulerCredentialIssue; specialistLauncher.ts: #assertCanStart and container start dispatch",
      "reason": "Credential issuance and container start do not recheck durable cancellation. dispatchSchedulerCredentialIssue checks documents, leases, execution status and credential status, but not runAcceptsWork. #assertCanStart checks local cancellation, deadline and documents; #assertAuthority checks leases. A durable cancellation request can leave approval and leases intact while moving the run to cancelling. If that request occurs during an awaited launcher operation, these paths can still issue credentials and start the container before asynchronous cleanup stops it.",
      "proposedFix": "Check durable run cancellation at credential issuance and container create/start dispatch, serialized with cancellation by the writer reservation. Keep cleanup available after cancellation. Add suspended-operation tests that request cancellation through the public coordinator while conformance, credential issuance or container inspection is pending, then assert no later unauthorized issue/create/start."
    }
  ],
  "resolvedPriorFindings": [
    {
      "finding": "Initial import checks publication instead of incoming ref",
      "assessment": "Addressed: importWorkflowLineage passes the parsed request.ref as additionalSourceRef before its transaction, and verification checks that registered worktree inside a durable attempt. The supplied regression tests changed incoming documents with no existing lineage ledger."
    },
    {
      "finding": "Repair-child asynchronous observations escape the outer dispatch guard",
      "assessment": "Addressed at the supplied OfficialRepairChildPort boundary: each createChild/createTaskRefCas invocation now uses dispatch after its observation. Suspended-read tests cover approval invalidation and run-owner takeover before both effects. The underlying production Beads implementation is not supplied, so its internal dispatch timing was not independently assessed."
    },
    {
      "finding": "Missing connected coordinator/launcher/restart journey",
      "assessment": "Addressed for the demonstrated fixture journey: both normative documents have public publication/review/approval/packet/launch coverage through the actual Docker launcher, durable result and artifact retention, reopen, and tamper denial."
    },
    {
      "finding": "Incomplete negative and compatibility coverage",
      "assessment": "Substantially improved: changed/deleted/artifact matrices, queue guards, unreadable-file test, WorkflowStore reopen migration and digest dimensions are supplied. Complete authority-boundary coverage remains unproved, particularly the dispatch paths identified above."
    }
  ],
  "requiredScenariosGenuinelyUnproved": [
    {
      "scenario": "DB-T04",
      "reason": "The supplied matrices do not prove refusal at every actual effect boundary. Ordinary Git dispatch and mismatched verification/commit workspaces remain concrete gaps."
    },
    {
      "scenario": "DB-T09",
      "reason": "The production Beads implementation beneath the repaired callback is absent, preventing confirmation that actual mutation initiation occurs before any further asynchronous gap."
    }
  ],
  "coverageLimits": [
    "Static review of supplied evidence only; no commands executed or state changed.",
    "Content hashes and compiled artifacts were not independently recomputed or verified.",
    "857 Linux passes with 17 skips and 110 enabled container passes are reported results, not independently reproduced results.",
    "The incoming-import regression isolates admission using an otherwise incomplete import request; it does not demonstrate successful composed public import.",
    "Connected tests use synthetic identities, fixture credentials and a deterministic consumer. Reopen verifies packet reconstruction and artifact retrieval, not a second successful execution.",
    "Hosted checks remain pending. No human approval, merge approval or managed orchestration qualification is established."
  ],
  "productDecisionsRequired": []
}
